declare(strict_types=1);
use OCA\NovaspacePlatform\Service\ConnectionStore as Store;
use OCA\NovaspacePlatform\Service\ConnectionPolicy as Policy;
rt('Existing connection preserves OAuth ceiling without implicit new app restrictions',function($f){$a=$f->store->approve('Owner',$f->client,Store::id(),'Name');$s=$f->store->status($f->client);check(!$s['accessPolicy']['configured']&&$s['accessPolicy']['enabled']);check($s['accessPolicy']['apps']['mail']==='read');});
rt('Owner saves main switch and all app modes atomically with readable audit fields',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];$apps=Policy::defaults()['apps'];$apps['files']='off';$apps['deck']='read';$r=$f->store->saveAccess('Owner',$c['connectionId'],1,Store::id(),false,$apps);check($r['committed']&&!$r['accessPolicy']['enabled']&&$r['accessPolicy']['apps']['files']==='off');$s=$f->store->status($f->client);check($s['active']&&$s['connection']['revision']===2);$h=$f->store->history('Owner');check($h[0]['action']==='connection.access_changed'||$h[1]['action']==='connection.access_changed');});
rt('Unrelated owner or differently cased identity cannot set policy',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];foreach(['Other','owner']as$o)registryDenied(fn()=>$f->store->saveAccess($o,$c['connectionId'],1,Store::id(),false,Policy::defaults()['apps']));check(!$f->store->policy($c['connectionId'])['configured']);});
rt('Stale form and revoked connection cannot be switched on',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];$f->store->revoke('Owner',$c['connectionId'],1,Store::id());registryDenied(fn()=>$f->store->saveAccess('Owner',$c['connectionId'],1,Store::id(),true,Policy::defaults()['apps']),'version_conflict');check(!$f->store->status($f->client)['active']);});
rt('Same request is idempotent, changed content cannot reuse it',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];$id=Store::id();$apps=Policy::defaults()['apps'];$f->store->saveAccess('Owner',$c['connectionId'],1,$id,false,$apps);$f->store->saveAccess('Owner',$c['connectionId'],1,$id,false,$apps);check(count($f->store->history('Owner'))===2);registryDenied(fn()=>$f->store->saveAccess('Owner',$c['connectionId'],1,$id,true,$apps),'request_conflict');});
rt('App modes are complete, bounded and cannot invent unsupported writes',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];$apps=Policy::defaults()['apps'];foreach(['unknown','missing','mail-write','bad-value']as$case){$bad=$apps;if($case==='unknown')$bad['admin']='write';if($case==='missing')unset($bad['files']);if($case==='mail-write')$bad['mail']='write';if($case==='bad-value')$bad['deck']='all';registryDenied(fn()=>$f->store->saveAccess('Owner',$c['connectionId'],1,Store::id(),true,$bad));}check(count($f->store->history('Owner'))===1);});
rt('Audit failure rolls back both policy and connection revision',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];$f->db->failEvent=true;registryDenied(fn()=>$f->store->saveAccess('Owner',$c['connectionId'],1,Store::id(),false,Policy::defaults()['apps']),'registry_outcome_unconfirmed');check(!$f->store->policy($c['connectionId'])['configured']&&$f->store->status($f->client)['connection']['revision']===1);});
rt('Two connections keep separate permissions',function($f){$a=$f->store->approve('Owner',$f->client,Store::id(),'One')['connection'];$f->client['clientHash']=str_repeat('d',64);$b=$f->store->approve('Owner',$f->client,Store::id(),'Two')['connection'];$f->store->saveAccess('Owner',$a['connectionId'],1,Store::id(),false,Policy::defaults()['apps']);check($f->store->policy($b['connectionId'])['enabled']);});
rt('Main switch can reenable own non-revoked connection and preserve chosen app limits',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'Name')['connection'];$apps=Policy::defaults()['apps'];$apps['mail']='off';$f->store->saveAccess('Owner',$c['connectionId'],1,Store::id(),false,$apps);$f->store->saveAccess('Owner',$c['connectionId'],2,Store::id(),true,$apps);check($f->store->policy($c['connectionId'])['enabled']&&$f->store->policy($c['connectionId'])['apps']['mail']==='off');});
rt('Native app-password caller cannot change owner permissions',function($f){cloud($f);registryDenied(fn()=>$f->service->saveAccess(Store::id(),1,Store::id(),'0',Policy::defaults()['apps']),'web_session_required');});
rt('Access form is a CSRF-protected POST route',function($f){$m=new ReflectionMethod(\OCA\NovaspacePlatform\Controller\ConnectionsController::class,'saveAccess');check(array_map(fn($a)=>$a->getName(),$m->getAttributes())===['OCP\\AppFramework\\Http\\Attribute\\NoAdminRequired']);$routes=require __DIR__.'/../app/appinfo/routes.php';check(count(array_filter($routes['routes'],fn($r)=>$r['name']==='connections#saveAccess'&&$r['verb']==='POST'))===1);});
rt('Access migration adds one table without editing existing connection rows',function($f){require_once __DIR__.'/../app/lib/Migration/Version000400Date20261018180000.php';$s=new SchemaFixture();$s->tables['ns_pf_connections']=new SchemaTable();$s->tables['ns_pf_events']=new SchemaTable();$m=new \OCA\NovaspacePlatform\Migration\Version000400Date20261018180000();$out=new class implements \OCP\Migration\IOutput{};$m->changeSchema($out,fn()=>$s,[]);check(count($s->tables)===3&&$s->tables['ns_pf_access']->primary===['conn_id']);try{$m->changeSchema($out,fn()=>$s,[]);}catch(RuntimeException){return;}throw new RuntimeException('Prior schema overwritten');});
rt('Rendered owner page shows selected limits main status scope ceiling and no unsupported mail write',function($f){$c=$f->store->approve('Owner',$f->client,Store::id(),'<Name>')['connection'];$apps=Policy::defaults()['apps'];$apps['files']='off';$f->store->saveAccess('Owner',$c['connectionId'],1,Store::id(),false,$apps);$p=webController($f)->index();$_=$p->params+['requesttoken'=>'<csrf>'];ob_start();include __DIR__.'/../app/templates/connections.php';$html=ob_get_clean();check(str_contains($html,'Hauptschalter ausgeschaltet')&&str_contains($html,'maximal erlaubten Zugriff')&&str_contains($html,'apps[mail]')&&!str_contains($html,'<Name>')&&!str_contains($html,'<csrf>'));preg_match('/<select[^>]*name="apps\[mail\]"[^>]*>(.*?)<\/select>/s',$html,$mail);check(isset($mail[1])&&!str_contains($mail[1],'value="write"'));});

rt('Notes addition preserves legacy nine-app policies and starts off without changing prior modes',function($f){$apps=Policy::defaults()['apps'];check($apps['notes']==='off');unset($apps['notes'], $apps['tasks'], $apps['contacts']);$apps['deck']='read';$apps['files']='off';$normalized=Policy::modes($apps);check($normalized['notes']==='off'&&$normalized['deck']==='read'&&$normalized['files']==='off');check(!array_key_exists('notes',$apps));$apps['notes']='write';check(Policy::modes($apps)['notes']==='write');});

rt('Tasks and Contacts default off, retain legacy Notes and require full new policy keys',function($f){$apps=Policy::defaults()['apps'];check($apps['tasks']==='off'&&$apps['contacts']==='off');unset($apps['tasks'],$apps['contacts']);$apps['notes']='write';$m=Policy::modes($apps);check($m['notes']==='write'&&$m['tasks']==='off'&&$m['contacts']==='off');$apps['tasks']='read';try{Policy::modes($apps);}catch(\OCA\NovaspacePlatform\Service\PlatformDenied){return;}throw new RuntimeException('Partial new schema accepted');});
